/**
 * On-site chat widget — the Telegram bot's own brain
 * (YeffoPrint_Telegram_Message_Handler::handle(), via class-web-chat-
 * controller.php) reached from a floating widget instead of Telegram.
 * Direct request, following research into "integrating a chat bot into
 * the site that does the same as the telegram bot": reuse, don't
 * rebuild — every reply here is generated by the exact same FAQ/order-
 * lookup/search/escalation logic the Telegram bot uses, so the two
 * stay in agreement automatically as either one improves.
 *
 * Deliberately NOT built on the theme's own `.yp-drawer` primitive
 * (site.js) — that's a full-page-backdrop modal (cart, search), the
 * right weight for "the customer explicitly opened this to do one
 * thing," but too heavy for a persistent chat widget someone keeps
 * open alongside browsing. This is its own small, anchored panel that
 * borrows .yp-drawer's visual language (radius/shadow tokens, the same
 * icon-button close control) without its backdrop/focus-trap behavior.
 *
 * Only enqueued when the Telegram bot itself is active (functions.php,
 * mirroring the REST endpoint's own YeffoPrint_Telegram_Settings::
 * is_enabled() gate) — turning the bot off turns this off too, since
 * it's answering with the bot's own brain.
 */

( function () {
	'use strict';

	if ( 'undefined' === typeof yeffoprintWebChat ) {
		return;
	}

	var SESSION_KEY = 'yp_web_chat_session_id';

	function getSessionId() {
		try {
			var stored = window.localStorage.getItem( SESSION_KEY );
			if ( stored && /^[0-9]+$/.test( stored ) ) {
				return stored;
			}
		} catch ( error ) {
			// Private browsing / storage disabled — fall through to a
			// fresh, unpersisted id for just this page load.
		}

		// Telegram's own private-chat ids are always positive, well under
		// this range in practice — collision with a real one, or with
		// another visitor's session, is astronomically unlikely, the same
		// assumption class-telegram-escalation.php's own chat_id-keyed
		// transients already rely on.
		var id = String( Math.floor( Math.random() * 900000000000 ) + 100000000000 );

		try {
			window.localStorage.setItem( SESSION_KEY, id );
		} catch ( error ) {
			// Nothing to persist to — this session just won't survive a reload.
		}

		return id;
	}

	function escapeHtml( str ) {
		var div = document.createElement( 'div' );
		div.textContent = String( str == null ? '' : str );
		return div.innerHTML;
	}

	var URL_PATTERN = /(https?:\/\/[^\s<]+)/g;

	/** Plain-text bot replies (never HTML) rendered safely: escape everything first, then turn already-escaped URLs into real links — never the other way around. */
	function formatReply( text ) {
		return escapeHtml( text )
			.replace( /\n/g, '<br>' )
			.replace( URL_PATTERN, function ( url ) {
				// escapeHtml() already turned a trailing "&" (a query string
				// separator) into "&amp;" — fine to keep as the link's own
				// href/text, browsers resolve the entity either way.
				return '<a href="' + url + '" target="_blank" rel="noopener noreferrer">' + url + '</a>';
			} );
	}

	function init() {
		var sessionId = getSessionId();
		var isOpen = false;
		var isSending = false;

		var root = document.createElement( 'div' );
		root.className = 'yp-chat-widget';
		root.innerHTML =
			'<button type="button" class="yp-chat-fab" aria-expanded="false" aria-label="Chat with YeffoBot">' +
				'<svg viewBox="0 0 24 24" fill="none" aria-hidden="true" class="yp-chat-fab__icon-open"><path d="M4 4h16v12H8l-4 4V4z" stroke="currentColor" stroke-width="2" stroke-linejoin="round" fill="none"/></svg>' +
				'<svg viewBox="0 0 24 24" fill="none" aria-hidden="true" class="yp-chat-fab__icon-close"><path d="M6 6l12 12M18 6L6 18" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg>' +
			'</button>' +
			'<div class="yp-chat-panel" hidden>' +
				'<div class="yp-chat-panel__header">' +
					'<span>YeffoBot</span>' +
					'<button type="button" class="yp-icon-button" data-yp-chat-close aria-label="Close chat">&times;</button>' +
				'</div>' +
				'<div class="yp-chat-panel__body" data-yp-chat-messages role="log" aria-live="polite"></div>' +
				'<form class="yp-chat-panel__form" data-yp-chat-form>' +
					'<input type="text" data-yp-chat-input placeholder="Ask a question…" autocomplete="off" maxlength="1000" />' +
					'<button type="submit" aria-label="Send">' +
						'<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M21.5 4.5L2.7 11.8c-1.2.5-1.2 1.2-.2 1.5l4.8 1.5 1.8 5.6c.2.6.4.8.9.8.4 0 .6-.2.9-.5l2.2-2.1 4.6 3.4c.8.5 1.4.2 1.6-.8l3-14c.3-1.2-.4-1.7-1.4-1.2z" fill="currentColor"/></svg>' +
					'</button>' +
				'</form>' +
			'</div>';

		document.body.appendChild( root );

		var fab = root.querySelector( '.yp-chat-fab' );
		var panel = root.querySelector( '.yp-chat-panel' );
		var messagesEl = root.querySelector( '[data-yp-chat-messages]' );
		var form = root.querySelector( '[data-yp-chat-form]' );
		var input = root.querySelector( '[data-yp-chat-input]' );

		function addMessage( who, html ) {
			var row = document.createElement( 'div' );
			row.className = 'yp-chat-message yp-chat-message--' + who;
			row.innerHTML = html;
			messagesEl.appendChild( row );
			messagesEl.scrollTop = messagesEl.scrollHeight;
		}

		function open() {
			if ( isOpen ) {
				return;
			}
			isOpen = true;
			panel.hidden = false;
			root.classList.add( 'is-open' );
			fab.setAttribute( 'aria-expanded', 'true' );

			if ( ! messagesEl.childElementCount ) {
				addMessage( 'bot', escapeHtml( yeffoprintWebChat.greeting ) );
			}

			window.setTimeout( function () { input.focus(); }, 50 );
		}

		function close() {
			if ( ! isOpen ) {
				return;
			}
			isOpen = false;
			panel.hidden = true;
			root.classList.remove( 'is-open' );
			fab.setAttribute( 'aria-expanded', 'false' );
			fab.focus();
		}

		fab.addEventListener( 'click', function () {
			if ( isOpen ) { close(); } else { open(); }
		} );

		root.querySelector( '[data-yp-chat-close]' ).addEventListener( 'click', close );

		document.addEventListener( 'keydown', function ( event ) {
			if ( 'Escape' === event.key && isOpen ) {
				close();
			}
		} );

		form.addEventListener( 'submit', function ( event ) {
			event.preventDefault();

			var text = input.value.trim();
			if ( ! text || isSending ) {
				return;
			}

			addMessage( 'user', escapeHtml( text ) );
			input.value = '';
			isSending = true;

			var typingEl = document.createElement( 'div' );
			typingEl.className = 'yp-chat-message yp-chat-message--bot yp-chat-message--typing';
			typingEl.textContent = '…';
			messagesEl.appendChild( typingEl );
			messagesEl.scrollTop = messagesEl.scrollHeight;

			fetch( yeffoprintWebChat.restUrl + 'web-chat/message', {
				method: 'POST',
				headers: { 'Content-Type': 'application/json', 'X-WP-Nonce': yeffoprintWebChat.nonce },
				body: JSON.stringify( { session_id: sessionId, text: text } )
			} )
				.then( function ( response ) {
					return response.json().then( function ( data ) {
						if ( ! response.ok ) {
							throw new Error( ( data && data.message ) || 'Something went wrong.' );
						}
						return data;
					} );
				} )
				.then( function ( data ) {
					typingEl.remove();
					addMessage( 'bot', formatReply( data.reply ) );
				} )
				.catch( function ( error ) {
					typingEl.remove();
					addMessage( 'bot', escapeHtml( error.message || 'Something went wrong — try again in a moment.' ) );
				} )
				.finally( function () {
					isSending = false;
				} );
		} );
	}

	if ( 'loading' === document.readyState ) {
		document.addEventListener( 'DOMContentLoaded', init );
	} else {
		init();
	}

	/**
	 * Lets a link — the order emails' own "Start live chat" option, for
	 * one — deep-link straight into an opened panel instead of landing on
	 * a page with a closed widget the visitor then has to notice and
	 * click themselves. Reads a plain query param rather than a hash so
	 * it survives being pasted into an email client that strips/rewrites
	 * URL fragments.
	 */
	function openFromUrlParam() {
		var params;
		try {
			params = new URLSearchParams( window.location.search );
		} catch ( error ) {
			return;
		}

		if ( 'open' !== params.get( 'yp_chat' ) ) {
			return;
		}

		var fab = document.querySelector( '.yp-chat-fab' );
		if ( fab ) {
			fab.click();
		}
	}

	if ( 'loading' === document.readyState ) {
		document.addEventListener( 'DOMContentLoaded', openFromUrlParam );
	} else {
		openFromUrlParam();
	}
} )();
